import (
	"bufio"
	"log"
	"net/http"
	"strings"
	"unicode"
	"unicode/utf8"

	"certadmin/internal/service"

	"github.com/gin-gonic/gin"
)

func (s *Server) handleCertificateCSV(c *gin.Context) {
	actor := actorFrom(c)
	filter, aerr := parseCertificateFilter(c, false)
	if aerr != nil {
		s.writeError(c, aerr)
		return
	}

	select {
	case s.exportSem <- struct{}{}:
		defer func() { <-s.exportSem }()
	default:
		s.writeError(c, &apiError{
			Status:  http.StatusServiceUnavailable,
			Code:    "TEMPORARILY_UNAVAILABLE",
			Message: "导出任务繁忙，请重试",
		})
		return
	}

	var (
		started bool
		writer  *bufio.Writer
		rows    int
	)
	err := s.svc.StreamCertificates(c.Request.Context(), actor.TenantID, filter,
		func() {
			c.Header("Content-Type", "text/csv; charset=utf-8")
			c.Header("Content-Disposition", `attachment; filename="certificates.csv"`)
			c.Status(http.StatusOK)
			c.Writer.WriteHeaderNow()
			started = true
			writer = bufio.NewWriterSize(c.Writer, 64*1024)
			_, _ = writer.WriteString("learnerName,courseTitle,serialNumber,issuedLocalDate\r\n")
		},
		func(row service.CertificateCSVRow) error {
			rows++
			if s.exportRowHook != nil {
				if err := s.exportRowHook(row, rows); err != nil {
					return err
				}
			}
			if err := writeCSVRecord(writer,
				protectFormula(row.LearnerName),
				protectFormula(row.CourseTitle),
				row.SerialNumber,
				row.IssuedLocalDate,
			); err != nil {
				return err
			}
			if rows%200 == 0 {
				return writer.Flush()
			}
			return nil
		})
	if err != nil {
		if !started {
			s.fail(c, err)
			return
		}
		log.Printf("request %s aborted CSV export after %d rows: %v", requestID(c), rows, err)
		panic(http.ErrAbortHandler)
	}
	if err := writer.Flush(); err != nil {
		log.Printf("request %s failed to flush CSV: %v", requestID(c), err)
		panic(http.ErrAbortHandler)
	}
}

func writeCSVRecord(w *bufio.Writer, fields ...string) error {
	for i, field := range fields {
		if i > 0 {
			if err := w.WriteByte(','); err != nil {
				return err
			}
		}
		if _, err := w.WriteString(csvField(field)); err != nil {
			return err
		}
	}
	_, err := w.WriteString("\r\n")
	return err
}

func csvField(value string) string {
	if !needsQuoting(value) {
		return value
	}
	return `"` + strings.ReplaceAll(value, `"`, `""`) + `"`
}

func needsQuoting(value string) bool {
	if value == "" {
		return false
	}
	if strings.ContainsAny(value, ",\"\r\n") {
		return true
	}
	first, _ := utf8.DecodeRuneInString(value)
	last, _ := utf8.DecodeLastRuneInString(value)
	if unicode.IsSpace(first) || unicode.IsSpace(last) {
		return true
	}
	return false
}

// protectFormula prefixes user-controlled text that could be interpreted as a
// spreadsheet formula. serialNumber is system generated and is not sanitized.
func protectFormula(value string) string {
	trimmed := strings.TrimLeftFunc(value, unicode.IsSpace)
	if trimmed == "" {
		return value
	}
	switch trimmed[0] {
	case '=', '+', '-', '@':
		return "'" + value
	default:
		return value
	}
}
// Package store opens the SQLite database, applies migrations and seeds demo data.
package store

import (
	"database/sql"
	"errors"
	"fmt"
	"net/url"
	"os"
	"path/filepath"
	"strings"

	_ "modernc.org/sqlite"
)

// DB holds one serialized write pool and a concurrent read pool.
type DB struct {
	Write *sql.DB
	Read  *sql.DB
	Path  string
}

// Open creates or opens the SQLite database at path. WAL, foreign keys and a
// busy timeout are configured per connection; reads use a query-only pool.
func Open(path string) (*DB, error) {
	abs, err := filepath.Abs(path)
	if err != nil {
		return nil, fmt.Errorf("resolve database path: %w", err)
	}
	if err := os.MkdirAll(filepath.Dir(abs), 0o755); err != nil {
		return nil, fmt.Errorf("create database directory: %w", err)
	}

	pragmas := url.Values{}
	pragmas.Add("_pragma", "busy_timeout(10000)")
	pragmas.Add("_pragma", "foreign_keys(1)")
	pragmas.Add("_pragma", "journal_mode(WAL)")
	pragmas.Add("_pragma", "synchronous(NORMAL)")

	writeDSN := "file:" + filepath.ToSlash(abs) + "?" + pragmas.Encode() + "&_txlock=immediate"
	write, err := sql.Open("sqlite", writeDSN)
	if err != nil {
		return nil, fmt.Errorf("open write database: %w", err)
	}
	write.SetMaxOpenConns(1)
	write.SetMaxIdleConns(1)
	write.SetConnMaxLifetime(0)
	if err := write.Ping(); err != nil {
		write.Close()
		return nil, fmt.Errorf("ping write database: %w", err)
	}

	readPragmas := url.Values{}
	readPragmas.Add("_pragma", "busy_timeout(10000)")
	readPragmas.Add("_pragma", "foreign_keys(1)")
	readPragmas.Add("_pragma", "query_only(1)")
	readDSN := "file:" + filepath.ToSlash(abs) + "?" + readPragmas.Encode()
	read, err := sql.Open("sqlite", readDSN)
	if err != nil {
		write.Close()
		return nil, fmt.Errorf("open read database: %w", err)
	}
	read.SetMaxOpenConns(8)
	read.SetMaxIdleConns(8)
	read.SetConnMaxLifetime(0)
	if err := read.Ping(); err != nil {
		write.Close()
		read.Close()
		return nil, fmt.Errorf("ping read database: %w", err)
	}

	return &DB{Write: write, Read: read, Path: abs}, nil
}

// Close releases both pools.
func (db *DB) Close() error {
	return errors.Join(db.Read.Close(), db.Write.Close())
}

// IsBusy reports whether err is a transient SQLite lock/busy error.
func IsBusy(err error) bool {
	if err == nil {
		return false
	}
	msg := strings.ToLower(err.Error())
	return strings.Contains(msg, "sqlite_busy") ||
		strings.Contains(msg, "sqlite_locked") ||
		strings.Contains(msg, "database is locked") ||
		strings.Contains(msg, "database table is locked")
}
import type {
  BulkOperationResult,
  CertificateDetail,
  CertificateFilters,
  CertificateListItem,
  Course,
