	}
	c.Data(status, "application/json; charset=utf-8", body)
}
package httpapi

import (
	"net/http"
	"regexp"

	"certadmin/internal/service"

	"github.com/gin-gonic/gin"
)

// Server wires the HTTP contract to the service layer.
type Server struct {
	svc           *service.Service
	engine        *gin.Engine
	exportSem     chan struct{}
	exportRowHook func(service.CertificateCSVRow, int) error
}

func New(svc *service.Service) *Server {
	s := &Server{
		svc:       svc,
		exportSem: make(chan struct{}, 2),
	}
	engine := gin.New()
	engine.HandleMethodNotAllowed = true
	engine.RedirectTrailingSlash = false
	engine.RedirectFixedPath = false
	engine.RemoveExtraSlash = false
	engine.Use(requestIDMiddleware(), recoveryMiddleware())
	engine.NoRoute(s.handleNotFound)
	engine.NoMethod(s.handleMethodNotAllowed)

	api := engine.Group("/api/v1", s.authMiddleware())
	api.GET("/me", s.handleMe)
	api.GET("/courses", s.handleCourses)
	api.GET("/courses/:courseId/enrollments", s.handleCourseEnrollments)
	api.POST("/courses/:courseId/bulk-operations", s.handleBulkIssue)
	api.GET("/learners/:learnerId/enrollments", s.handleLearnerEnrollments)
	api.GET("/certificates", s.handleCertificates)
	api.GET("/certificates.csv", s.handleCertificateCSV)
	api.GET("/certificates/:certificateId", s.handleCertificateDetail)
	api.PUT("/certificates/:certificateId/revocation", s.handleRevocation)

	s.engine = engine
	return s
}

func (s *Server) Handler() http.Handler { return s.engine }

func (s *Server) handleNotFound(c *gin.Context) {
	s.writeError(c, &apiError{Status: http.StatusNotFound, Code: "NOT_FOUND", Message: "未知 API 路径"})
}

type routeRule struct {
	pattern *regexp.Regexp
	methods []string
}

var routeRules = []routeRule{
	{regexp.MustCompile(`^/api/v1/me$`), []string{"GET"}},
	{regexp.MustCompile(`^/api/v1/courses$`), []string{"GET"}},
	{regexp.MustCompile(`^/api/v1/courses/[1-9][0-9]*/enrollments$`), []string{"GET"}},
	{regexp.MustCompile(`^/api/v1/courses/[1-9][0-9]*/bulk-operations$`), []string{"POST"}},
	{regexp.MustCompile(`^/api/v1/learners/[1-9][0-9]*/enrollments$`), []string{"GET"}},
	{regexp.MustCompile(`^/api/v1/certificates$`), []string{"GET"}},
	{regexp.MustCompile(`^/api/v1/certificates\.csv$`), []string{"GET"}},
	{regexp.MustCompile(`^/api/v1/certificates/[1-9][0-9]*$`), []string{"GET"}},
	{regexp.MustCompile(`^/api/v1/certificates/[1-9][0-9]*/revocation$`), []string{"PUT"}},
}

func (s *Server) handleMethodNotAllowed(c *gin.Context) {
	for _, rule := range routeRules {
		if rule.pattern.MatchString(c.Request.URL.Path) {
			c.Header("Allow", rule.methods[0])
			s.writeError(c, &apiError{
				Status:  http.StatusMethodNotAllowed,
				Code:    "METHOD_NOT_ALLOWED",
				Message: "该路径不支持此 HTTP 方法",
			})
			return
		}
	}
	s.handleNotFound(c)
}
package httpapi

import (
	"bufio"
	"log"
	"net/http"
	"strings"
	"unicode"
	"unicode/utf8"

	"certadmin/internal/service"

	"github.com/gin-gonic/gin"
)

func (s *Server) handleCertificateCSV(c *gin.Context) {
	actor := actorFrom(c)
	filter, aerr := parseCertificateFilter(c, false)
	if aerr != nil {
		s.writeError(c, aerr)
		return
	}

	select {
	case s.exportSem <- struct{}{}:
		defer func() { <-s.exportSem }()
	default:
		s.writeError(c, &apiError{
			Status:  http.StatusServiceUnavailable,
			Code:    "TEMPORARILY_UNAVAILABLE",
			Message: "导出任务繁忙，请重试",
		})
		return
	}

	var (
		started bool
		writer  *bufio.Writer
		rows    int
	)
	err := s.svc.StreamCertificates(c.Request.Context(), actor.TenantID, filter,
		func() {
			c.Header("Content-Type", "text/csv; charset=utf-8")
			c.Header("Content-Disposition", `attachment; filename="certificates.csv"`)
			c.Status(http.StatusOK)
			c.Writer.WriteHeaderNow()
			started = true
			writer = bufio.NewWriterSize(c.Writer, 64*1024)
			_, _ = writer.WriteString("learnerName,courseTitle,serialNumber,issuedLocalDate\r\n")
		},
		func(row service.CertificateCSVRow) error {
			rows++
			if s.exportRowHook != nil {
				if err := s.exportRowHook(row, rows); err != nil {
					return err
				}
			}
			if err := writeCSVRecord(writer,
				protectFormula(row.LearnerName),
				protectFormula(row.CourseTitle),
				row.SerialNumber,
				row.IssuedLocalDate,
			); err != nil {
				return err
			}
			if rows%200 == 0 {
				return writer.Flush()
			}
			return nil
		})
	if err != nil {
		if !started {
			s.fail(c, err)
			return
		}
		log.Printf("request %s aborted CSV export after %d rows: %v", requestID(c), rows, err)
		panic(http.ErrAbortHandler)
	}
	if err := writer.Flush(); err != nil {
		log.Printf("request %s failed to flush CSV: %v", requestID(c), err)
		panic(http.ErrAbortHandler)
	}
}

func writeCSVRecord(w *bufio.Writer, fields ...string) error {
	for i, field := range fields {
		if i > 0 {
			if err := w.WriteByte(','); err != nil {
				return err
			}
		}
		if _, err := w.WriteString(csvField(field)); err != nil {
			return err
		}
	}
	_, err := w.WriteString("\r\n")
	return err
}

func csvField(value string) string {
	if !needsQuoting(value) {
		return value
	}
	return `"` + strings.Re…4477 tokens truncated…ue()
}

function eligibilityText(enrollment: {
  issuanceEligibility?: { eligible: boolean; reasonCode: Enrollment['issuanceEligibility']['reasonCode'] }
}): string {
  const eligibility = enrollment.issuanceEligibility
  if (!eligibility) return '不可发证'
  if (eligibility.eligible) return '可发证'
  switch (eligibility.reasonCode) {
    case 'COURSE_INCOMPLETE':
      return '课程未完成'
    case 'ALREADY_CERTIFIED':
      return '已有有效证书'
    case 'CERTIFICATE_REVOKED':
      return '已有吊销证书'
    default:
      return '不可发证'
  }
}

function resultStatusText(status: string): string {
  if (status === 'issued') return '已发证'
  if (status === 'skipped') return '已跳过'
  return '失败'
}

function resultReasonText(reason: string | null): string {
  switch (reason) {
    case 'COURSE_INCOMPLETE':
      return '课程未完成'
    case 'ALREADY_CERTIFIED':
      return '已有有效证书'
    case 'CERTIFICATE_REVOKED':
      return '已有吊销证书'
    case 'ISSUANCE_ERROR':
      return '发证错误'
    default:
      return '—'
  }
}

async function downloadCsv(): Promise<void> {
  exporting.value = true
  try {
    const blob = await exportCertificates(actorToken.value, filters)
    const url = URL.createObjectURL(blob)
    const anchor = document.createElement('a')
    anchor.href = url
    anchor.download = 'certificates.csv'
    document.body.appendChild(anchor)
    anchor.click()
    anchor.remove()
    URL.revokeObjectURL(url)
    ElMessage.success('CSV 已开始下载')
  } catch (err) {
