} from './types'

export class ApiError extends Error {
  status: number
  code: string
  requestId: string
  details: Array<{ field: string; reason: string }>

  constructor(status: number, code: string, message: string, requestId: string, details: Array<{ field: string; reason: string }>) {
    super(message)
    this.name = 'ApiError'
    this.status = status
    this.code = code
    this.requestId = requestId
    this.details = details
  }
}

interface RequestOptions {
  method?: string
  body?: unknown
  headers?: Record<string, string>
  signal?: AbortSignal
}

async function request<T>(token: string, path: string, options: RequestOptions = {}): Promise<T> {
  const headers: Record<string, string> = {
    Authorization: `Bearer ${token}`,
    ...options.headers
  }
  let body: string | undefined
  if (options.body !== undefined) {
    headers['Content-Type'] = 'application/json'
    body = JSON.stringify(options.body)
  }
  const response = await fetch(path, {
    method: options.method ?? 'GET',
    headers,
    body,
    signal: options.signal
  })
  if (!response.ok) {
    let code = 'INTERNAL_ERROR'
    let message = `请求失败（HTTP ${response.status}）`
    let requestId = response.headers.get('X-Request-Id') ?? ''
    let details: Array<{ field: string; reason: string }> = []
    try {
      const payload = await response.json()
      if (payload?.error) {
        code = payload.error.code ?? code
        message = payload.error.message ?? message
        requestId = payload.error.requestId ?? requestId
        details = payload.error.details ?? []
      }
    } catch {
      // Keep the HTTP fallback when the body is not JSON.
    }
    throw new ApiError(response.status, code, message, requestId, details)
  }
  return (await response.json()) as T
}

function certificateQuery(filters: CertificateFilters): string {
  const params = new URLSearchParams()
  if (filters.q.trim() !== '') params.set('q', filters.q.trim())
  if (filters.status !== '') params.set('status', filters.status)
  if (filters.courseId !== undefined) params.set('courseId', String(filters.courseId))
  params.set('sortBy', filters.sortBy)
  params.set('sortOrder', filters.sortOrder)
  params.set('page', String(filters.page))
  params.set('pageSize', String(filters.pageSize))
  return params.toString()
}

export function getMe(token: string, signal?: AbortSignal): Promise<Me> {
  return request<Me>(token, '/api/v1/me', { signal })
}

export function listCourses(token: string, signal?: AbortSignal): Promise<Page<Course>> {
  return request<Page<Course>>(token, '/api/v1/courses?page=1&pageSize=100', { signal })
}

export function listCertificates(token: string, filters: CertificateFilters, signal?: AbortSignal): Promise<Page<CertificateListItem>> {
  return request<Page<CertificateListItem>>(token, `/api/v1/certificates?${certificateQuery(filters)}`, { signal })
}

export function getCertificate(token: string, id: number, signal?: AbortSignal): Promise<CertificateDetail> {
  return request<CertificateDetail>(token, `/api/v1/certificates/${id}`, { signal })
}

export function listCourseEnrollments(token: string, courseId: number, signal?: AbortSignal): Promise<Page<Enrollment>> {
  return request<Page<Enrollment>>(token, `/api/v1/courses/${courseId}/enrollments?page=1&pageSize=100`, { signal })
}

export function bulkIssue(token: string, courseId: number, idempotencyKey: string, signal?: AbortSignal): Promise<BulkOperationResult> {
  return request<BulkOperationResult>(token, `/api/v1/courses/${courseId}/bulk-operations`, {
    method: 'POST',
    body: {},
    headers: { 'Idempotency-Key': idempotencyKey },
    signal
  })
}

export function revokeCertificate(token: string, id: number, signal?: AbortSignal): Promise<RevocationResult> {
  return request<RevocationResult>(token, `/api/v1/certificates/${id}/revocation`, {
    method: 'PUT',
    body: {},
    signal
  })
}

export async function exportCertificates(token: string, filters: CertificateFilters, signal?: AbortSignal): Promise<Blob> {
  const params = new URLSearchParams()
  if (filters.q.trim() !== '') params.set('q', filters.q.trim())
  if (filters.status !== '') params.set('status', filters.status)
  if (filters.courseId !== undefined) params.set('courseId', String(filters.courseId))
  params.set('sortBy', filters.sortBy)
  params.set('sortOrder', filters.sortOrder)
  const response = await fetch(`/api/v1/certificates.csv?${params.toString()}`, {
    headers: { Authorization: `Bearer ${token}` },
    signal
  })
  if (!response.ok) {
    let message = `导出失败（HTTP ${response.status}）`
    try {
      const payload = await response.json()
      message = payload?.error?.message ?? message
    } catch {
      // Keep the HTTP fallback.
    }
    throw new Error(message)
  }
  return response.blob()
}
// Package store opens the SQLite database, applies migrations and seeds demo data.
package store

import (
	"database/sql"
	"errors"
	"fmt"
	"net/url"
	"os"
	"path/filepath"
	"strings"

	_ "modernc.org/sqlite"
)

// DB holds one serialized write pool and a concurrent read pool.
type DB struct {
	Write *sql.DB
	Read  *sql.DB
	Path  string
}

// Open creates or opens the SQLite database at path. WAL, foreign keys and a
// busy timeout are configured per connection; reads use a query-only pool.
func Open(path string) (*DB, error) {
	abs, err := filepath.Abs(path)
	if err != nil {
		return nil, fmt.Errorf("resolve database path: %w", err)
	}
	if err := os.MkdirAll(filepath.Dir(abs), 0o755); err != nil {
		return nil, fmt.Errorf("create database directory: %w", err)
	}

	pragmas := url.Values{}
	pragmas.Add("_pragma", "busy_timeout(10000)")
	pragmas.Add("_pragma", "foreign_keys(1)")
	pragmas.Add("_pragma", "journal_mode(WAL)")
	pragmas.Add("_pragma", "synchronous(NORMAL)")

	writeDSN := "file:" + filepath.ToSlash(abs) + "?" + pragmas.Encode() + "&_txlock=immediate"
	write, err := sql.Open("sqlite", writeDSN)
	if err != nil {
		return nil, fmt.Errorf("open write database: %w", err)
	}
	write.SetMaxOpenConns(1)
	write.SetMaxIdleConns(1)
	write.SetConnMaxLifetime(0)
	if err := write.Ping(); err != nil {
		write.Close()
		return nil, fmt.Errorf("ping write database: %w", err)
	}

	readPragmas := url.Values{}
	readPragmas.Add("_pragma", "busy_timeout(10000)")
	readPragmas.Add("_pragma", "foreign_keys(1)")
	readPragmas.Add("_pragma", "query_only(1)")
	readDSN := "file:" + filepath.ToSlash(abs) + "?" + readPragmas.Encode()
	read, err := sql.Open("sqlite", readDSN)
	if err != nil {
		write.Close()
		return nil, fmt.Errorf("open read database: %w", err)
	}
	read.SetMaxOpenConns(8)
	read.SetMaxIdleConns(8)
	read.SetConnMaxLifetime(0)
	if err := read.Ping(); err != nil {
		write.Close()
		read.Close()
		return nil, fmt.Errorf("ping read database: %w", err)
	}

	return &DB{Write: write, Read: read, Path: abs}, nil
}

// Close releases both pools.
func (db *DB) Close() error {
	return errors.Join(db.Read.Close(), db.Write.Close())
}

// IsBusy reports whether err is a transient SQLite lock/busy error.
func IsBusy(err error) bool {
	if err == nil {
		return false
	}
	msg := strings.ToLower(err.Error())
	return strings.Contains(msg, "sqlite_busy") ||
		strings.Contains(msg, "sqlite_locked") ||
		strings.Contains(msg, "database is locked") ||
		strings.Contains(msg, "database table is locked")
}
package main

import (
	"context"
	"errors"
	"flag"
	"log"
	"net/http"
	"os"
	"os/signal"
	"path/filepath"
	"syscall"
	"time"

	"certadmin/internal/httpapi"
	"certadmin/internal/service"
	"certadmin/internal/store"

	"github.com/gin-gonic/gin"
)

func main() {
	dbPath := flag.String("db", "data/demo.db", "SQLite database path")
	addr := flag.String("addr", ":8080", "HTTP listen address")
	webDir := flag.String("web-dir", "web/dist", "built frontend directory")
	flag.Parse()
	gin.SetMode(gin.ReleaseMode)

	db, err := store.Open(*dbPath)
	if err != nil {
		log.Fatalf("open database: %v", err)
	}
	defer db.Close()
	if err := db.Migrate(); err != nil {
		log.Fatalf("migrate: %v", err)
	}
	seeded, err := db.SeedIfEmpty()
	if err != nil {
		log.Fatalf("seed: %v", err)
	}
	if seeded {
		log.Printf("initialized demo data in %s", db.Path)
	}

	svc := service.New(db)
	srv := httpapi.New(svc)
	mux := http.NewServeMux()
	mux.Handle("/api", srv.Handler())
	mux.Handle("/api/", srv.Handler())
	mux.Handle("/", spaHandler(*webDir))

	httpServer := &http.Server{
		Addr:              *addr,
		Handler:           mux,
		ReadHeaderTimeout: 10 * time.Second,
		IdleTimeout:       120 * time.Second,
	}

	go func() {
		log.Printf("certificate admin listening on %s (db=%s)", *addr, db.Path)
		if err := httpServer.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			log.Fatalf("listen: %v", err)
		}
	}()

	stop := make(chan os.Signal, 1)
	signal.Notify(stop, syscall.SIGINT, syscall.SIGTERM)
	<-stop

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	if err := httpServer.Shutdown(ctx); err != nil {
		log.Printf("shutdown: %v", err)
	}
}

// spaHandler serves the built frontend and falls back to index.html for
// non-API paths. API paths are routed separately and keep JSON 404s.
func spaHandler(dir string) http.Handler {
	root := http.Dir(dir)
	files := http.FileServer(root)
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet && r.Method != http.MethodHead {
			http.NotFound(w, r)
			return
		}
		clean := filepath.Clean("/" + r.URL.Path)
		if clean == "/" {
			serveIndex(w, r, dir)
			return
		}
		if info, err := root.Open(clean); err == nil {
			info.Close()
			files.ServeHTTP(w, r)
			return
		}
		serveIndex(w, r, dir)
	})
}

func serveIndex(w http.ResponseWriter, r *http.Request, dir string) {
	index := filepath.Join(dir, "index.html")
	if _, err := os.Stat(index); err != nil {
		http.Error(w, "frontend not built: run `npm --prefix web install && npm --prefix web run build`", http.StatusServiceUnavailable)
		return
	}
	http.ServeFile(w, r, index)
}

